(() => {
  'use strict';
  const {stages,repositories,papers,connections}=window.HUB;
  const main=document.querySelector('#main');
  const dialog=document.querySelector('#repo-dialog');
  const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const ext=(url,label,cls='text-link')=>`<a class="${cls}" href="${escape(url)}" target="_blank" rel="noopener noreferrer">${escape(label)} <span aria-hidden="true">↗</span></a>`;
  const repo=name=>repositories.find(r=>r.name===name);
  const paper=id=>papers.find(p=>p.id===id);
  const repoButton=(name,label)=>`<button type="button" data-repo="${escape(name)}" class="repo-chip">${escape(label||repo(name)?.title||name)}</button>`;
  const researchLink=id=>`<a class="text-link" href="#thesis/${id==='synthesis'?'appendices':id}">Read the research <span aria-hidden="true">↗</span></a>`;
  const sectionLinks=(names,id)=>`<div class="section-links">${names.map(n=>`<button type="button" data-repo="${n}">${escape(repo(n).title)} ↗</button>`).join('')}${researchLink(id)}</div>`;
  const credit=n=>`Ranasinghe et al. (2025), <a href="https://doi.org/10.3390/s25216582" target="_blank" rel="noopener noreferrer">Sensors 25, 6582, Fig. ${n}</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>. Cropped from the paper; results unchanged.`;
  const figures=window.PAPER_FIGURES;
  const figureCredit=f=>f.reuse_status==='verified-open-license'?credit(f.figure):`Ranasinghe et al. · <a href="#thesis/${f.paper_id}">${escape(paper(f.paper_id).label)}</a>, local manuscript, Fig. ${f.figure}. Unmodified figure.`;
  function paperFigure(id,extra=''){const f=figures.find(x=>x.id===id);return `<figure class="paper-figure ${extra}"><div class="paper-figure-heading"><span class="status-label">${escape(f.evidence_type)}</span><h3>${escape(f.story_title)}</h3></div><a class="image-zoom paper-figure-image" href="${f.path}" target="_blank" rel="noopener noreferrer" aria-label="Open full-resolution figure: ${escape(f.story_title)}"><img src="${f.path}" width="${f.width}" height="${f.height}" loading="lazy" alt="${escape(f.story_description)}"></a><figcaption class="caption"><p>${escape(f.story_description)}</p><p class="paper-figure-credit">${figureCredit(f)}</p><a class="text-link" href="${f.path}" target="_blank" rel="noopener noreferrer">Inspect the complete figure ↗</a></figcaption></figure>`}
  let page='',lastTrigger=null;
  let filters={q:'',group:'all',type:'all'};
  let selectedStage='calibrate';
  const svg=(body,label,w=400,h=240)=>`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${escape(label)}" xmlns="http://www.w3.org/2000/svg">${body.replace(/<text\b[^>]*>[\s\S]*?<\/text>/g,'')}</svg>`;
  const schematicScene=(mode='fusion')=>{
    const labels={camera:'Shaded roof supports and conveyor, illustrating camera appearance.',lidar:'Matching roof-support and conveyor surfaces represented by blue LiDAR points.',fusion:'The same surface geometry represented by points coloured from the illustrated camera view.'};
    return `<img class="fusion-illustration" src="public/assets/diagrams/fusion-${mode==='fusion'?'colourised':mode}.svg" alt="${labels[mode]} Original illustrative geometry, not measured data." loading="lazy" width="640" height="440">`;
  };
  const methodGraphics={
    spatial:()=>svg('<rect x="114" y="54" width="176" height="126" rx="5" fill="white" stroke="#a8bbd5"/>'+Array.from({length:6},(_,row)=>Array.from({length:8},(_,col)=>`<rect x="${116+col*21.5}" y="${56+row*20.5}" width="21.5" height="20.5" fill="${(row+col)%2?'#1c354f':'#fff'}"/>`).join('')).join('')+'<g fill="none" stroke="#2578d6" stroke-width="1.5"><path d="M48 205L137 77m-89 128 133-87m-133 87 178-46m-178 46 220-87"/><circle cx="137" cy="77" r="4"/><circle cx="181" cy="118" r="4"/><circle cx="226" cy="159" r="4"/></g><rect x="30" y="190" width="38" height="28" rx="5" fill="#1959c7"/><text x="190" y="224" text-anchor="middle" font-size="12" fill="#58718e" font-family="Arial">One paired capture · shared geometry</text>','Camera and LiDAR correspondences on a checkerboard'),
    enclosure:()=>svg('<path d="M114 189c0-150 186-150 186 0" stroke="#8da8c1" stroke-width="14" fill="none"/><path d="M36 79L147 139l144 70" stroke="#b9c7d9" stroke-dasharray="5 5" fill="none" stroke-width="2"/><path d="M36 79L147 139l150 21 64 40" stroke="#1959c7" fill="none" stroke-width="3"/><path d="M147 139l-30 38" stroke="#8097b3" stroke-dasharray="4 4"/><circle cx="36" cy="79" r="6" fill="#1959c7"/><g font-family="Arial" font-size="12" fill="#546e8c"><text x="147" y="52">Protective optical surface</text><text x="32" y="57">Light ray</text><text x="277" y="147">Refracted path</text></g>','A light ray changes direction as it passes through a dome'),
    timing:()=>svg('<g font-family="Arial" font-size="12" fill="#526d8b"><text x="34" y="65">Camera</text><text x="34" y="140">LiDAR</text><text x="153" y="211">Same event, different observation times</text></g><path d="M40 92H362M40 164H362" stroke="#bccbe0"/><path d="M42 91h46l27-30 34 59 30-56 25 27h128" fill="none" stroke="#1959c7" stroke-width="3"/><path d="M42 163h87l27-30 34 59 30-56 25 27h87" fill="none" stroke="#167870" stroke-width="3"/><path d="M149 118v58m41-56v58m-41-7h41" stroke="#7753ac" stroke-dasharray="3 3"/><text x="161" y="191" fill="#7753ac" font-family="Arial" font-size="13">Δt</text>','Two time series with an observation-time offset'),
    light:()=>{
      const frame=(row,label)=>`<svg viewBox="27 ${row==='raw'?45:284} 284 202" role="img" aria-label="${label}" xmlns="http://www.w3.org/2000/svg"><title>${label}</title><image href="public/assets/evidence/low-light-comparison.png" width="1334" height="927"/></svg>`;
      return `<figure class="low-light-preview"><div class="low-light-heading"><span class="status-label">Published comparison</span><span>1 lux · Frame 1</span></div><div class="low-light-pair"><div class="low-light-sample"><a class="image-zoom" href="public/assets/evidence/low-light-comparison.png" target="_blank" rel="noopener noreferrer" aria-label="Inspect the complete published low-light figure, including this raw frame">${frame('raw','Raw corridor camera frame captured at 1 lux; display crop from Figure 9(a), frame 1.')}</a><strong>Raw capture</strong></div><span class="low-light-arrow" aria-hidden="true">→</span><div class="low-light-sample"><a class="image-zoom" href="public/assets/evidence/low-light-comparison.png" target="_blank" rel="noopener noreferrer" aria-label="Inspect the complete published low-light figure, including this enhanced frame">${frame('enhanced','The matching corridor frame after low-light enhancement; display crop from Figure 9(b), frame 1.')}</a><strong>Enhanced capture</strong></div></div><figcaption>Same frame from the four-camera research rig. Display crops from panels (a) and (b); pixel values unchanged.<br>Ranasinghe et al. (2025), <a href="https://doi.org/10.3390/s25216582" target="_blank" rel="noopener noreferrer">Sensors, Fig. 9</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>. <a href="public/assets/evidence/low-light-comparison.png" target="_blank" rel="noopener noreferrer">View all frames and smoothed results ↗</a></figcaption></figure>`;
    }
  };
  const methods=[
    {id:'spatial',label:'Spatial alignment',question:'Are we looking at the same place?',text:'Extrinsic calibration estimates how the two sensors are positioned relative to one another. It tells the software where a measured 3D point belongs in the image.',result:'A shared geometric frame',repos:['single-shot-lidar-camera-calibration'],paper:'spatial'},
    {id:'enclosure',label:'Enclosure correction',question:'Does the enclosure bend the measurement?',text:'A curved transparent dome refracts light. Ray tracing models this bending; correction tables and calibration with the enclosure in place address its effect on both sensing channels.',result:'Geometry that accounts for the optical surface',repos:['enclosure-aware-lidar-correction'],paper:'measurement'},
    {id:'timing',label:'Observation timing',question:'Did both sensors see the same moment?',text:'A rotating target gives the sensors a common moving reference. Comparing its observed angle helps estimate a relative observation-time offset, even when timestamps alone are insufficient.',result:'An estimated offset between observations',repos:['livox-avia-camera-timing','rotating-target-calibration-studio'],paper:'timing'},
    {id:'light',label:'Low-light processing',question:'Can we recover useful appearance?',text:'Image enhancement makes dark scene information more visible, while colour correction and temporal smoothing help keep colourisation consistent. Performance depends on the platform and lighting conditions.',result:'More useful colour information under evaluated conditions',repos:['Sensor_Computer'],paper:'colour'}
  ];
  const methodLabels={spatial:['Paired capture','Shared geometry'],enclosure:['Optical surface','Reference ray','Refracted ray'],timing:['Camera signal','LiDAR signal','Observation-time offset']};
  const diagramKey=labels=>`<ul class="diagram-key">${labels.map(label=>`<li>${label}</li>`).join('')}</ul>`;
  function publicationSummary(){
    const summary=window.PUBLICATION_SUMMARY,groups=summary.groups;
    const counts={published:groups.published.length,under_review:groups.under_review.length,conference:groups.conference.length,patents:summary.patents.length};
    const total=counts.published+counts.under_review+counts.conference;
    const ordinal=n=>n%100>=11&&n%100<=13?'th':({1:'st',2:'nd',3:'rd'}[n%10]||'th');
    const paperCard=(id,group)=>{
      const p=paper(id),j=summary.journals[summary.journal_for_paper[id]],conference=summary.conferences[id];
      return `<article class="publication-card" data-publication="${id}">${j||conference?`<p class="publication-venue">${escape(j?.name||conference.name)}${conference?' ('+escape(conference.short_name)+')':''}</p>`:''}<h4>${escape(p.title)}</h4><p>${escape(p.authors)}</p>${j?`<div class="journal-metrics"><div><span>Impact Factor${j.impact_factor_year?' · '+j.impact_factor_year:''}</span><strong>${j.impact_factor.toFixed(1)}</strong></div><div><span>CiteScore · ${j.citescore_year}</span><strong>${j.citescore.toFixed(1)}</strong></div><div><span>Best CiteScore percentile · ${j.citescore_year}</span><strong>${j.percentile}${ordinal(j.percentile)}</strong><small>${escape(j.category)} · Rank ${escape(j.rank)}</small></div></div>`:''}<div class="publication-links">${ext(p.url,group==='under_review'?'Read manuscript':'Read paper')}${j?ext(j.publisher_url,'Journal metrics')+ext(j.scopus_url,'CiteScore ranking'):''}</div></article>`;
    };
    return `<div class="dialog-head"><span>My research outputs</span><button type="button" class="close-button" data-close-dialog aria-label="Close publication summary"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><div class="dialog-body"><div class="eyebrow">Publication summary</div><h2 id="dialog-title">${total} papers supporting my PhD.</h2><div class="publication-totals">${[[counts.published,'Published journal articles'],[counts.under_review,'Journal papers under review'],[counts.conference,'Conference papers'],[counts.patents,'Patent applications']].map(([n,label])=>`<div><strong>${n}</strong><span>${label}</span></div>`).join('')}</div><nav class="publication-jump" aria-label="Publication summary sections">${[['published','Journals'],['under_review','Under review'],['conference','Conferences'],['patents','Patents']].map(([id,label])=>`<button type="button" data-publication-section="${id}">${label}</button>`).join('')}</nav><section class="publication-group" id="publication-published"><h3>Published journal articles</h3>${groups.published.map(id=>paperCard(id,'published')).join('')}</section><section class="publication-group" id="publication-under_review"><h3>Journal papers under review</h3>${groups.under_review.map(id=>paperCard(id,'under_review')).join('')}</section><section class="publication-group" id="publication-conference"><h3>Published conference papers</h3>${groups.conference.map(id=>paperCard(id,'conference')).join('')}</section><section class="publication-group" id="publication-patents"><h3>Patent applications</h3>${summary.patents.map(p=>`<article class="publication-card"><p class="publication-venue">${escape(p.status)}</p><h4>${escape(p.title)}</h4>${p.title.includes(p.number)?'':`<p>Application ${escape(p.number)}${p.filed?' · Filed '+escape(p.filed):''}</p>`}${p.applicants?`<p>${escape(p.applicants)}</p>`:''}${p.url?ext(p.url,'View filing record'):''}</article>`).join('')}</section></div>`;
  }
  function openPublications(trigger){lastTrigger=trigger||document.activeElement;dialog.classList.add('publication-dialog');document.querySelector('#dialog-content').innerHTML=publicationSummary();if(!dialog.open)dialog.showModal();dialog.scrollTop=0;document.querySelector('[data-close-dialog]').focus();}
  function protectedUnit(){return `<figure class="unit-illustration" aria-labelledby="unit-illustration-title"><div class="unit-cutaway"><img src="public/assets/diagrams/protected-unit.svg" alt="Illustrative protected unit with an Avia-inspired silver LiDAR, green optical window, side cooling fins, separate camera and processing module beneath a transparent dome." width="900" height="620" loading="lazy"><span class="unit-marker unit-marker-1" aria-hidden="true">1</span><span class="unit-marker unit-marker-2" aria-hidden="true">2</span><span class="unit-marker unit-marker-3" aria-hidden="true">3</span><span class="unit-marker unit-marker-4" aria-hidden="true">4</span><span class="unit-marker unit-marker-5" aria-hidden="true">5</span></div><figcaption><span class="status-label">Inside the sensing unit</span><h3 id="unit-illustration-title">Two sensing channels.<br>One protected unit.</h3><ol class="unit-components">${[['Livox Avia LiDAR','Measures the 3D geometry of the scene.'],['Camera','Captures appearance for point-cloud colourisation.'],['Embedded processing','Acquires, corrects and combines the observations.'],['Optical dome','Provides the transparent sensing surface.'],['Enclosure','Houses the sensors and electronics.']].map((x,i)=>`<li><span class="unit-number" aria-hidden="true">${i+1}</span><div><strong>${x[0]}</strong><p>${x[1]}</p></div></li>`).join('')}</ol></figcaption></figure>`}
  function methodPanel(id){const m=methods.find(x=>x.id===id);const picture=id==='spatial'?paperFigure('registration-validation','paper-figure-compact'):id==='light'?methodGraphics[id]():`<div class="method-graphic">${methodGraphics[id]()}</div>${diagramKey(methodLabels[id])}`;return `<div class="method-picture${['light','spatial'].includes(id)?' method-picture-evidence':''}">${picture}</div><div><h3>${m.question}</h3><p>${m.text}</p><div class="method-result">↳ ${m.result}</div>${sectionLinks(m.repos,m.paper)}</div>`}

  function story(){
    return `<div class="hero container">
      ${window.PORTFOLIO_UI.hero(figureCredit)}
      ${window.LONGWALL_SCENE.render()}
      ${window.PORTFOLIO_UI.progression()}
    </div>
    <section class="story-section container" id="story-context"><div class="section-heading"><div><div class="eyebrow">01 / The challenge</div><h2>A changing workplace.<br>A fragmented view.</h2></div><p>At a longwall face, a shearer cuts coal while a line of hydraulic supports protects the work area. Machinery, people and the surrounding geometry move together. Understanding their relationships needs more than isolated measurements.</p></div><div class="split"><div class="copy"><h3>What is near what?<br>And what is changing?</h3><p>Cameras show appearance, but distance and clearance are hard to judge from a flat view. Gas, dust, ground and worker-location sensors remain essential. Spatial sensing can add geometric context to their evidence.</p><div class="mini-points"><div><strong>Distance & clearance</strong><span>Where objects are relative to one another.</span></div><div><strong>Change over time</strong><span>How movement alters the scene.</span></div></div>${researchLink('review')}</div>${paperFigure('longwall-mounting')}</div></section>
    <section class="story-section container" id="story-capture"><div class="section-heading"><div><div class="eyebrow">02 / Capture</div><h2>Shape and colour.<br>A richer observation.</h2></div><p>A point cloud is a collection of measured 3D positions. Adding camera colour makes those points easier to interpret while preserving the LiDAR’s geometric information.</p></div><div class="fusion-grid"><div class="fusion-card">${schematicScene('camera')}<div class="fusion-copy"><span class="fusion-kicker">01 / Appearance</span><h3>Camera image</h3><p>Colour, texture and visual context.</p></div></div><span class="fusion-sign" aria-hidden="true">+</span><div class="fusion-card">${schematicScene('lidar')}<div class="fusion-copy"><span class="fusion-kicker">02 / Geometry</span><h3>LiDAR scan</h3><p>Distance measurements in 3D.</p></div></div><span class="fusion-sign" aria-hidden="true">→</span><div class="fusion-card">${schematicScene('fusion')}<div class="fusion-copy"><span class="fusion-kicker">03 / Combined view</span><h3>Colourised observation</h3><p>Geometry and appearance in one view.</p></div></div></div><p class="caption">Illustrative views explain fusion; the published examples below show actual research outputs.</p><div class="evidence-block"><div><span class="status-label">Published research output</span><h3>Useful appearance,<br>even under low light.</h3><p>These reconstructed corridor views compare dark, well-lit and enhanced dark captures from the four-camera research rig. This is a different platform from the later enclosed single-camera unit.</p>${sectionLinks(['Sensor_Computer'],'colour')}</div><figure><a class="image-zoom" href="public/assets/evidence/colourised-reconstruction.png" target="_blank" rel="noopener noreferrer" aria-label="Open full-resolution published colourised reconstruction figure"><img src="public/assets/evidence/colourised-reconstruction.png" alt="Complete published Figure 10, comparing SLAM corridor reconstruction under dark, well-lit and enhanced dark captures." loading="lazy" width="1359" height="657"></a><figcaption class="caption">${credit(10)} Open the image to inspect every panel.</figcaption></figure></div></section>
    <section class="story-section container" id="story-reliable"><div class="section-heading"><div><div class="eyebrow">03 / Make it reliable</div><h2>Before combining views,<br>make them agree.</h2></div><p>Good-looking output is not enough. Spatial position, refraction, observation time and image quality each affect how reliably the sensors describe the same scene.</p></div><div class="method-lab"><div class="method-tabs" role="tablist" aria-label="Measurement reliability methods">${methods.map((m,i)=>`<button type="button" role="tab" id="method-tab-${m.id}" aria-controls="method-panel" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-method="${m.id}">${m.label}</button>`).join('')}</div><div class="method-panel" id="method-panel" role="tabpanel" tabindex="0" aria-labelledby="method-tab-spatial">${methodPanel('spatial')}</div></div><p class="technical-note">An estimated time offset differs from residual error after correction. Results apply to the hardware and conditions evaluated.</p><details class="map-alt"><summary>See the published low-light comparison</summary><figure class="evidence-block"><div><h3>Raw → enhanced → smoothed</h3><p>Four frames at 1 lux show the effect of enhancement and temporal smoothing.</p><figcaption class="caption">${credit(9)}</figcaption></div><a class="image-zoom" href="public/assets/evidence/low-light-comparison.png" target="_blank" rel="noopener noreferrer" aria-label="Open full-resolution low-light comparison"><img src="public/assets/evidence/low-light-comparison.png" alt="Complete published Figure 9: four camera frames at 1 lux, with raw, enhanced and temporally smoothed results." loading="lazy" width="1334" height="927"></a></figure></details></section>
    <section class="story-section container" id="story-unit"><div class="section-heading"><div><div class="eyebrow">04 / Integrate</div><h2>A sensing method<br>becomes a physical unit.</h2></div><p>Putting sensors inside a protective enclosure changes the engineering problem. Optics, heat, power, computation and communications must work together.</p></div>${protectedUnit()}<div class="split">${paperFigure('unit-hardware-architecture','paper-figure-tall')}<div class="copy"><ol class="pipeline-list"><li><strong>Acquire</strong>Read LiDAR, images and inertial measurements.</li><li><strong>Correct and combine</strong>Apply appropriate calibration, timing and processing.</li><li><strong>Process within constraints</strong>Manage heat, data volume and embedded computation.</li><li><strong>Transmit a useful observation</strong>Send colourised point clouds and device diagnostics.</li></ol>${sectionLinks(['Sensor_Computer','3D_monitoring_device_simulation_underground'],'hardware')}<p class="caption">Bench testing and simulation establish pre-deployment evidence. Enclosure certification does not establish whole-system or site acceptance.</p></div></div></section>
    <section class="story-section container" id="story-array"><div class="section-heading"><div><div class="eyebrow">05 / Reconstruct</div><h2>Many local views.<br>One common scene.</h2></div><p>One device sees a local region. An array needs overlapping views, suitable mounting geometry and reliable alignment to build a wider scene.</p></div><div class="array-introduction"><div><h3>A convincing fit<br>can still be the wrong fit.</h3><p>Repeated roof supports look similar. Aligning surfaces alone can place a device in the wrong position. The array research uses known spacing as a physical constraint, alongside roof-plane alignment and global pose optimisation.</p></div><div><p>Explore the coverage and alignment tools, then follow the manuscript figures from local observations to a merged scene.</p>${sectionLinks(['Lidar_camera_FOV_analysis','Multi_device_reconstruction-pose_graph'],'array')}</div></div>${paperFigure('array-fusion-before-after','paper-figure-featured')}<div class="paper-figure-grid">${paperFigure('array-pose-graph')}${paperFigure('array-single-unit-cloud')}</div><p class="technical-note">The array reconstruction examples use simulated longwall data; the single-unit figure shows colourisation rather than multi-device alignment.</p><div class="operator-evidence"><div class="operator-introduction"><div><span class="status-label">Desktop monitoring</span><h3>From streams to an inspectable scene.</h3></div><div><p>The Central Monitoring Platform adds recording, measurements and device diagnostics to individual and combined 3D views.</p>${sectionLinks(['Central_Monitoring_Platform'],'array')}</div></div>${paperFigure('array-monitoring-interface')}</div></section>
    <section class="story-section container" id="story-safety"><div class="section-heading"><div><div class="eyebrow">06 / Interpret</div><h2>Seeing an object<br>is only the beginning.</h2></div><p>Safety interpretation asks what objects mean in relation to one another. The research combines perception with structured relationships, deterministic rules and contextual reasoning.</p></div><div class="reasoning-flow"><div><small>OBSERVE</small><strong>3D point clouds</strong><p>Measured positions and colour.</p></div><div><small>DETECT</small><strong>Scene elements</strong><p>Semantic classes and uncertainty signals.</p></div><div><small>RELATE</small><strong>Scene & temporal graphs</strong><p>Objects, distances and changing relationships.</p></div><div><small>INTERPRET</small><strong>Hazard evidence</strong><p>Rules, context and relevant history.</p></div></div><div class="scenario"><div><span class="status-label" style="color:var(--purple)">An illustrative proximity scenario</span><h3>A person near moving equipment.</h3><p>A proximity rule links the detected person and machinery; context and historical evidence help explain the situation.</p>${sectionLinks(['Scene-Graph_Mine-Safety'],'safety')}</div><div>${safetyGraph()}<p class="caption">Illustrative personnel–equipment relationship; no measured distance or live alert.</p></div></div>${paperFigure('safety-scene-graph-pipeline','paper-figure-featured')}<div class="evidence-numbers"><div><strong>115</strong><span>controlled hazard scenarios</span></div><div><strong>57 → 76 → 93%</strong><span>reported coverage: rules → contextual reasoning → memory</span></div></div><p class="technical-note">Scenario coverage is separate from perception accuracy and processing throughput. MineGraph Studio demonstrates one-frame inspection; it does not connect to live sensors or implement the full temporal research pipeline. The reconstructed-array-to-reasoning connection remains proposed.</p></section>
    <section class="story-section container" id="story-extensions"><div class="section-heading"><div><div class="eyebrow">07 / Further applications</div><h2>More questions<br>from the same geometry.</h2></div><p>Once 3D observations are available, other tools can explore movement and shape. Each has its own purpose and evidence boundary.</p></div><div class="extensions">${[['Creep_Monitoring','↝','Concept / prototype','Creep monitoring','Monitor unwanted movement of underground roof-support structures using reference markers and recorded scans. Operating-face performance is not established.'],['Dynamic_Object_Detection','◎','Supporting tool','Motion in a persistent scene','Identify moving foreground points while accounting for a stationary or slightly moving sensor. Named monitoring integration remains unverified.'],['Meshing_toolkit','△','Research toolkit','From points to surfaces','Build coloured surface meshes and benchmark scan consistency. A mesh is a representation of the available observations, not additional measured geometry.']].map(x=>`<article class="extension"><span class="icon" aria-hidden="true">${x[1]}</span><span class="status-label">${x[2]}</span><h3>${x[3]}</h3><p>${x[4]}</p><div class="section-links"><button type="button" data-repo="${x[0]}">Explore this application ↗</button></div></article>`).join('')}</div></section>
    <section class="closing container" id="story-next" aria-labelledby="closing-title"><div class="closing-heading"><div class="eyebrow">Where my research leads</div><h2 id="closing-title">From seeing the face to understanding the scene.</h2><ol class="closing-sequence" aria-label="My research progression"><li>Measure reliably</li><li>Reconstruct the scene</li><li>Interpret relationships</li></ol></div><div class="closing-story"><p>My next challenge is to connect the methods developed across these studies into a continuous workflow, from sensor acquisition to safety interpretation.</p><p>Sustained testing at an operating longwall face will be needed to evaluate that workflow as a whole.</p><div class="actions"><a class="button" href="#tools">Explore my tools <span aria-hidden="true">↗</span></a><a class="button secondary" href="#thesis">Follow my thesis <span aria-hidden="true">↗</span></a></div></div></section>${window.PEOPLE.render()}`;
  }
  function safetyGraph(){return '<div class="relationship-graph" role="img" aria-label="Illustrative graph: a person is near equipment, related to scene context and rule evidence."><div class="relationship-node relationship-context">Scene context</div><span class="relationship-link" aria-hidden="true"></span><div class="relationship-pair"><div class="relationship-node">Person</div><div class="relationship-edge">near<span aria-hidden="true">→</span></div><div class="relationship-node">Equipment</div></div><span class="relationship-link" aria-hidden="true"></span><div class="relationship-node relationship-rule">Rule evidence</div></div>'}

  function tools(){return `<div class="container tools-page"><div class="page-intro"><div class="eyebrow">The research ecosystem</div><h1>Explore the tools.<br>Understand the connections.</h1><p class="intro">${repositories.length} repositories support a shared research story. Some exchange data, some share methods, and some suggest future workflows. Select a stage to see the difference.</p></div><section class="map-shell" aria-labelledby="map-title"><div class="map-heading"><div><h2 id="map-title">From observation to interpretation</h2><p>The stage layout describes the research progression; detailed connections below identify the actual evidence.</p></div><div class="legend" aria-label="Connection legend"><span><i></i>Documented interface</span><span><i class="method"></i>Shared method / support</span><span><i class="future"></i>Proposed connection</span></div></div><div class="stage-map"><svg class="map-line" viewBox="0 0 1000 380" preserveAspectRatio="none" aria-hidden="true"><path data-for="capture calibrate" class="connection-active" d="M220 95H500" fill="none" stroke="#167870" stroke-dasharray="6 5" stroke-width="2"/><path data-for="calibrate protect" class="connection-active" d="M560 95H860" fill="none" stroke="#167870" stroke-dasharray="6 5" stroke-width="2"/><path data-for="protect reconstruct" d="M855 97Q988 100 988 180T855 285" fill="none" stroke="#1959c7" stroke-width="2"/><path data-for="reconstruct interpret" d="M840 286H550" fill="none" stroke="#ab572e" stroke-dasharray="2 5" stroke-width="2"/><path data-for="interpret extend" d="M480 286H180" fill="none" stroke="#ab572e" stroke-dasharray="2 5" stroke-width="2"/></svg>${stages.map((s,i)=>`<button type="button" class="stage-node" data-stage="${s.id}" aria-pressed="${s.id===selectedStage}" aria-controls="map-detail"><span class="node-num">0${i+1}</span><strong>${s.title}</strong><small>${s.subtitle}</small></button>`).join('')}</div><div id="map-detail" class="map-detail" aria-live="polite">${stageDetail(selectedStage)}</div><details class="map-alt"><summary>Accessible text view of all repository connections</summary><ol>${connections.map(c=>`<li><strong>${escape(c.from)} → ${escape(c.to)}</strong><br>${escape(c.label)} · ${kindLabel(c.kind)}. ${escape(c.basis)}</li>`).join('')}</ol></details></section><section aria-labelledby="catalogue-title"><div class="catalogue-heading"><h2 id="catalogue-title">Find your next tool.</h2><span class="repo-count" id="repo-count" aria-live="polite">${repositories.length} repositories</span></div><div class="filters"><div class="filter-field"><label for="repo-search">Search tools, inputs or methods</label><input id="repo-search" type="search" placeholder="Search the tools…" value="${escape(filters.q)}"></div><div class="filter-field"><label for="type-filter">Interface</label><select id="type-filter"><option value="all">All interfaces</option>${[...new Set(repositories.map(r=>r.type))].map(t=>`<option${filters.type===t?' selected':''}>${t}</option>`).join('')}</select></div></div><div class="group-tabs" role="group" aria-label="Filter by research area">${[['all','All tools'],['calibration','Calibration'],['sensing','Sensing'],['reconstruction','Reconstruction'],['interpretation','Interpretation'],['extensions','Further applications']].map(x=>`<button type="button" data-group="${x[0]}" aria-pressed="${filters.group===x[0]}">${x[1]}</button>`).join('')}</div><p class="catalogue-access-note">Conceptual tool illustrations. Study figures and reuse terms are in the details. Access checked 8 October 2026.</p><div class="repo-grid" id="repo-grid">${repositoryCards()}</div></section></div>`}
  const kindLabel=k=>({interface:'Documented data interface',method:'Shared method / supporting tool',future:'Proposed future connection'}[k]);
  function connectionHTML(c,compact=false,current=null){const endpoint=n=>current?(n===current?'This tool':repoButton(n)):escape(n);return `<li class="connection-item ${c.kind}"><strong>${escape(c.label)}</strong><span>${endpoint(c.from)} → ${endpoint(c.to)}</span><span>${kindLabel(c.kind)}${compact?'':` · ${escape(c.basis)}`}</span></li>`}
  function stageDetail(id){const s=stages.find(x=>x.id===id),edges=connections.filter(c=>s.repos.includes(c.from)||s.repos.includes(c.to));return `<div><h3>${s.subtitle}</h3><p>${s.description}</p><div class="map-output">Output: ${s.output}</div><div class="repo-chips">${s.repos.map(n=>repoButton(n)).join('')}</div><div class="section-links">${researchLink(s.paper)}</div></div><div><h4 style="font-size:1.125rem;letter-spacing:0">Relevant relationships</h4><ul class="connection-list">${edges.slice(0,4).map(c=>connectionHTML(c,true)).join('')}</ul>${edges.length>4?`<details class="map-alt"><summary>${edges.length-4} more connections</summary><ul class="connection-list">${edges.slice(4).map(c=>connectionHTML(c,true)).join('')}</ul></details>`:''}</div>`}
  function selectStage(id){selectedStage=id;document.querySelectorAll('[data-stage]').forEach(t=>t.setAttribute('aria-pressed',String(t.dataset.stage===id)));document.querySelector('#map-detail').innerHTML=stageDetail(id);document.querySelectorAll('.map-line path').forEach(p=>p.classList.toggle('connection-active',p.dataset.for.split(' ').includes(id)));}
  function accessInfo(r){const v=window.REPOSITORY_STATUS[r.name];return v||{public:r.visibility==='Public',licence:'Unverified',reviewDate:'2026-10-08'}}
  function filtered(){return repositories.filter(r=>{return(filters.group==='all'||r.group===filters.group)&&(filters.type==='all'||r.type===filters.type)&&[r.title,r.name,r.problem,r.approach,r.inputs,r.outputs].join(' ').toLowerCase().includes(filters.q.toLowerCase().trim())})}
  function repositoryCards(){const list=filtered(),ui=window.PORTFOLIO_UI;return list.length?list.map(r=>{const v=accessInfo(r),profile=window.PORTFOLIO.tools[r.name],category=({calibration:'Calibration',sensing:'Sensing',reconstruction:'Reconstruction',interpretation:'Safety',extensions:'Further applications'})[r.group];return `<article class="repo-card">${ui.visual(r,figureCredit)}<div class="repo-card-content"><p>${escape(profile.purpose)}</p><div class="repo-meta"><span>${escape(r.type)}</span><span>${ui.accessLabel(v)}</span><span>${v.demo?'Live demo':v.public?'Documentation available':'Documentation-only profile'}</span></div><div class="repo-actions">${ext(`https://github.com/maninka123/${r.name}`,'View Repository')}${v.demo?ext(v.demo,'View Demo'):''}<a class="text-link" href="${ui.research(r.papers[0])}">${r.papers[0]==='synthesis'?'Related Research':'Related Paper'} \u2197</a></div><button type="button" class="repo-open" data-repo="${r.name}" aria-label="Explore ${escape(r.title)}">Explore tool <span aria-hidden="true">\u2197</span></button></div></article>`}).join(''):`<p class="no-results">No tools match these filters. <button type="button" class="repo-chip" data-reset-filters>Clear filters</button></p>`}

  function refreshCards(){document.querySelector('#repo-grid').innerHTML=repositoryCards();document.querySelector('#repo-count').textContent=`${filtered().length} of ${repositories.length} repositories`;document.querySelectorAll('[data-group]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.group===filters.group)))}
  function repositoryImage(r){return window.PORTFOLIO_UI.visual(r,figureCredit,true)}
  function openRepository(name,trigger){dialog.classList.remove('publication-dialog');const r=repo(name);if(!r)return;if(page==='tools')selectStage((stages.find(s=>s.repos.includes(name))||stages[0]).id);if(!dialog.open)lastTrigger=trigger||document.activeElement;const v=accessInfo(r),edges=connections.filter(c=>c.from===name||c.to===name),extraRelated=r.related.filter(n=>!edges.some(c=>c.from===n||c.to===n));const demo=v.demo&&/^https:\/\//.test(v.demo)?v.demo:null;
    document.querySelector('#dialog-content').innerHTML=`<div class="dialog-head"><span>${r.type} · ${r.group}</span><button type="button" class="close-button" data-close-dialog aria-label="Close tool details"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><div class="dialog-body"><h2 id="dialog-title">${r.title}</h2><code class="exact-name">${r.name}</code><p>${r.problem}</p><h3>The approach</h3><p>${r.approach}</p>${repositoryImage(r)}${window.PORTFOLIO_UI.explore(r,v)}<div class="detail-grid"><div><h3>Inputs</h3><p>${r.inputs}</p></div><div><h3>Outputs</h3><p>${r.outputs}</p></div><div><h3>Role in the story</h3><p>${r.role}</p></div><div><h3>Evidence & development</h3><p>${r.status}</p></div></div><h3>Related tools</h3><ul class="connection-list">${edges.map(c=>connectionHTML(c,false,name)).join('')||'<li>No direct repository connection is documented.</li>'}</ul>${extraRelated.length?`<div class="repo-chips">${extraRelated.map(n=>repoButton(n)).join('')}</div>`:''}<h3 style="margin-top:2rem">The research</h3><ul class="paper-links">${r.papers.map(id=>id==='synthesis'?'<li><a href="#thesis/appendices" data-dialog-nav>Chapter 7 · Synthesis and future work ↗</a></li>':`<li><a href="#thesis/${id}" data-dialog-nav>${paper(id).chapter} · ${paper(id).label} ↗</a></li>`).join('')}</ul>${window.PORTFOLIO_UI.access(r,v,ext)}<div class="actions">${ext(`https://github.com/maninka123/${name}`,'View repository','button')}${demo?ext(demo,'Open browser demo','button secondary'):''}${v.readme?ext(v.readme,'Documentation','text-link'):''}</div></div>`;
    if(!dialog.open)dialog.showModal();dialog.scrollTop=0;document.querySelector('[data-close-dialog]').focus();
  }
  function closeDialog(){dialog.close();if(lastTrigger?.isConnected)lastTrigger.focus()}
  const thesisSections=[['overview','Overview & objectives'],['chapters','Chapter sequence'],['papers','Paper register'],['mapping','Software mapping'],['reproducibility','Reproducibility'],['appendices','Appendices & future work']];
  function paperEntry(p){
    const related=repositories.filter(r=>r.papers.includes(p.id));
    return `<article class="paper-entry" id="paper-${p.id}" aria-labelledby="paper-title-${p.id}"><div class="paper-heading"><span class="paper-slot">${escape(p.chapter.includes('Appendix')?p.chapter:'Chapter '+p.chapter)} &middot; ${escape(p.label)}</span><span class="paper-status">${escape(p.status)}</span></div><h3 id="paper-title-${p.id}">${escape(p.title)}</h3><div class="paper-record"><p class="paper-authors">${escape(p.authors)}</p><p>${escape(p.venue)}</p></div><div class="paper-details"><p class="contribution"><strong>Distinct contribution.</strong> ${escape(p.contribution)}</p><p><strong>Validation setting.</strong> ${escape(p.evidence)}</p></div>${related.length||p.url?`<div class="paper-actions">${related.length?`<div class="repo-chips">${related.map(r=>repoButton(r.name)).join('')}</div>`:''}${p.url?ext(p.url,p.id==='hardware'?'Read earlier public manuscript':'Read paper / public record'):''}</div>`:''}</article>`;
  }

  function thesis(){return `<div class="container"><div class="page-intro thesis-title"><div class="eyebrow">An academic view</div><h1>Integrated LiDAR–camera sensing.<br>From methods to safety reasoning.</h1><p class="intro">Thesis by publication · Pasindu Ranasinghe</p><div class="thesis-affiliation"><p><span>School of Minerals and Energy Resources Engineering</span><span class="affiliation-divider" aria-hidden="true">|</span><a class="affiliation-rank affiliation-subject" href="https://www.unsw.edu.au/engineering/our-schools/minerals-and-energy-resources-engineering" target="_blank" rel="noopener noreferrer" aria-label="3rd globally for Mineral and Mining Engineering in QS Subject Rankings 2026"><strong>World #3</strong><span>· QS Subject Rankings 2026</span></a></p><p><span>UNSW Sydney</span><span class="affiliation-divider" aria-hidden="true">|</span><a class="affiliation-rank" href="https://www.unsw.edu.au/about-us/excellence/rankings-reputation" target="_blank" rel="noopener noreferrer" aria-label="19th globally in QS World University Rankings 2027"><strong>World #19</strong><span>· QS Rankings 2027</span></a></p></div></div><div class="academic-grid"><nav class="academic-nav" aria-label="Thesis sections"><span class="label">The thesis map</span>${thesisSections.map(x=>`<a href="#thesis/${x[0]}">${x[1]}</a>`).join('')}</nav><div class="academic-body"><section id="thesis-overview"><h2>Overview & research objectives</h2><p>The thesis develops a pathway from reliable enclosed LiDAR–camera observations to spatial reconstruction and safety interpretation for longwall operations. Requirements motivate enabling methods; engineering integrates the unit; array reconstruction supplies wider spatial context; perception and reasoning interpret the scene.</p><ol class="objectives"><li><strong>Design and build a sensing unit</strong> for continuous longwall face monitoring. Principal evidence: Chapter 4.</li><li><strong>Calibrate the unit and develop accurate, real-time colourised 3D processing.</strong> Methods in Chapter 3; implementation in Chapters 4–5.</li><li><strong>Deploy multiple units as an array and interpret the reconstructed scene</strong> for underground safety decision support. Chapters 5–6 establish capabilities through pre-deployment and controlled evidence; operating-face deployment remains to be validated.</li></ol><div class="boundary"><h3>What the programme establishes</h3><p>Analytical, laboratory, recorded-data, simulation and controlled-scenario evidence for separate stages. It does not establish sustained end-to-end operation on an active underground longwall face.</p></div></section><section id="thesis-chapters"><h2>The chapter sequence</h2><ol class="chapter-list">${[['Introduction','Problem, research gap, objectives and distinct contributions.'],['Literature review','Monitoring requirements and deployment-readiness criteria.'],['Enabling methods for enclosed sensing','3.1 Spatial calibration · 3.2 Enclosure and timing · 3.3 Temporal target · 3.4 Colourisation.'],['A unit within a certified flameproof enclosure','Physical integration, thermal constraints and pre-deployment validation.'],['Scaling to a face-wide array','Efficient processing, coverage, spacing-constrained alignment and reconstruction.'],['From 3D perception to safety reasoning','Perception, uncertainty, graph representation, rules, contextual reasoning and memory.'],['Discussion and conclusions','Cross-study synthesis, readiness, limitations and future validation.']].map((x,i)=>`<li><span class="ch">0${i+1}</span><div><strong>${x[0]}</strong><small>${x[1]}</small></div></li>`).join('')}</ol></section><section id="thesis-papers"><h2>Paper register & distinct contributions</h2><p>This register links each study to its thesis chapter and contribution. Version notes identify earlier linked manuscripts.</p>${papers.map(p=>paperEntry(p)).join('')}</section><section id="thesis-mapping"><h2>Repositories, papers & chapters</h2><p>Shared support does not imply a live interface or an independently novel contribution in every chapter.</p><div class="table-wrap"><table><thead><tr><th>Repository</th><th>Research location</th><th>Role</th></tr></thead><tbody>${repositories.map(r=>`<tr><td><button type="button" data-repo="${r.name}">${r.name}</button></td><td>${r.papers.map(id=>id==='synthesis'?'Chapter 7 / supporting work':paper(id).chapter).join(', ')}</td><td>${r.role}</td></tr>`).join('')}</tbody></table></div></section><section id="thesis-reproducibility"><h2>Software & reproducibility</h2><p>The repositories provide implementations and instructions for the methods and applications in my research. Each repository links to its own documentation and terms.</p><p>For examination, Appendix D should map each software or data package to a fixed release/commit, dependency record, usage instructions and the results it supports. GitHub links alone are not a fixed examination archive. Confidential mine data and partner material need separate release decisions.</p><p>This hub contains source records and an asset register. It does not redistribute repository code or the original manuscripts.</p><a class="text-link" href="#sources">Inspect the sources & attribution record ↗</a></section><section id="thesis-appendices"><h2>Appendices & future work</h2><ul class="appendix-list"><li><strong>Appendix A:</strong> Earlier dome-refraction paper, with overlap to Section 3.2 disclosed.</li><li><strong>Appendix B:</strong> Literature-review audit, search criteria and supporting maturity classification.</li><li><strong>Appendix C:</strong> Verified application documentation. The supplied v3 manual now describes Central Monitoring application 1.0.1; earlier planning notes about missing manuals are stale.</li><li><strong>Appendix D:</strong> Fixed software/data archives and reproducibility records.</li><li><strong>Appendix E:</strong> Other supporting paper appendices, simulator/data specifications and permitted patent material.</li></ul><p>Next validation stages: single-unit underground testing; surveyed multi-unit reconstruction; environmental robustness and sustained duty; then joint acquisition-to-reasoning trials with operational error and human-use evaluation. These are proposed future stages, not completed deployment milestones.</p></section></div></div></div>`}
  function sources(){return `<div class="container sources"><div class="page-intro"><div class="eyebrow">Inspectable evidence</div><h1>Sources & image credits.</h1><p class="intro">The story is grounded in the supplied thesis documents, published research and public repository documentation. Diagrams explain concepts; evidence images retain the original scientific panels.</p></div><h2>Content sources</h2><ul><li>GitHub Repository Portfolio Overview: the revised PhD portfolio, with ${repositories.length} included repository descriptions (8 October 2026).</li><li>Thesis completion plan and skeleton, September 2026; Chapter Map and Thesis Storyline: chapter ownership, objectives, contributions and evidence boundaries.</li><li>Current journal/conference papers: platform distinctions, evaluation settings and metrics.</li><li>Central Monitoring Platform user guide v3: application 1.0.1, documented transports and operator functions.</li><li>Public GitHub READMEs and licence records, checked 8 October 2026: access, current documentation, supported interfaces and limitations.</li><li>${ext('https://research.unsw.edu.au/people/professor-simit-raval/publications','UNSW Research publication record','')}: current safety journal citation, superseding the local plan’s under-review status. ${ext('https://papers.ssrn.com/sol3/papers.cfm?abstract_id=7513129','SSRN rotating-target manuscript','')}: a public paper link missing from the older plan.</li></ul><h2>Published evidence images</h2>${[['1','multi-camera-prototype','Four-camera research prototype','The trolley rig is distinct from the protected single-camera mine unit.'],['8','registration-validation','Alignment and projection validation','Complete original calibration panels retained.'],['9','low-light-comparison','Raw, enhanced and smoothed images','Four frames at 1 lux; all three comparison rows retained.'],['10','colourised-reconstruction','Colourised corridor reconstruction','Dark, well-lit and enhanced dark captures; all comparison panels retained.']].map(x=>`<article class="source-card"><h3>${x[2]}</h3><p>${x[3]}</p><p>${credit(x[0])}</p>${ext(`public/assets/evidence/${x[1]}.png`,'Inspect full-resolution figure')}</article>`).join('')}<article class="source-card"><h3>Rotating-target studio screenshot</h3><p>Genuine face-on simulation view from the public studio README. Pasindu Ranasinghe, UNSW (2026). Used under <a href="public/assets/evidence/rotating-target-studio.LICENSE.txt">MIT with complete notice</a>; image unmodified. Noise-free simulated target geometry, not physical calibration accuracy.</p><a class="text-link" href="public/assets/evidence/rotating-target-studio.png" target="_blank" rel="noopener noreferrer">Inspect screenshot ?</a></article><h2>Figures from my manuscripts</h2><p>Seven unmodified figures from my hardware, array and safety manuscripts are included. Figure numbers refer to the inspected local versions, which may differ from public manuscripts or the final journal edition. Authorization is scoped to this hub; no open-content licence is claimed.</p>${figures.filter(f=>f.reuse_status==='author-authorized-for-this-hub').map(f=>`<article class="source-card"><h3>${escape(f.story_title)}</h3><p>${escape(f.story_description)}</p><p>${escape(f.attribution)}</p><a class="text-link" href="#thesis/${f.paper_id}">Research record ↗</a>${ext(f.path,'Inspect full-resolution figure')}</article>`).join('')}<h2>Original explanatory diagrams</h2><p>The longwall, protected-unit, fusion, calibration and relationship schematics were created for this hub from the supplied scientific concepts. They are editable SVGs and are explicitly illustrative. The protected-unit sensor is an original drawing based on the <a href="https://www.livoxtech.com/avia" target="_blank" rel="noopener noreferrer">Livox Avia external form</a>; the enclosure layout is explanatory and not to scale. No generated scientific result, fictional measurement or field-deployment photograph is used.</p><p>Partner hardware photographs, confidential mine reconstructions and source images without resolved public reuse remain outside the distributable assets. Review copies are kept only in the local verification folder.</p><h2>Publication and journal metric records</h2><p>The header summary brings together my published papers, journal manuscripts under review, conference papers and related patent applications. Journal Impact Factors link to the publishers; 2025 CiteScore values and highest category percentiles link to Scopus.</p>${ext('source-records/publication-summary.json','Inspect the publication summary record')}<h2>Records & remaining gaps</h2><div class="actions"><a class="button secondary" href="source-records/public-source-register.json" target="_blank" rel="noopener noreferrer">Source register ↗</a><a class="button secondary" href="docs/research-map.md" target="_blank" rel="noopener noreferrer">Text research map ↗</a></div><ul style="margin-top:2rem"><li>Several public repositories have no detected licence. No code or imagery from those projects is redistributed.</li><li>Hardware arXiv and earlier safety manuscripts have different titles from the local revisions. Links are labelled with their version context.</li><li>Final author contribution statements, examination archives and the second patent’s full details need author records.</li></ul></div>`}
  function render(){const parts=(location.hash.slice(1)||'story').split('/');let next=parts[0];if(!['story','tools','thesis','sources'].includes(next))next='story';const changed=next!==page;if(changed){page=next;main.innerHTML=({story,tools,thesis,sources})[page]();document.title=`${({story:'The Story',tools:'Explore the Tools',thesis:'The Thesis',sources:'Sources & Credits'})[page]} · Below the Surface`;document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(page==='tools'){refreshCards();selectStage(selectedStage);}}const target=parts[1];if(target){const id=page==='story'?`story-${target}`:paper(target)?`paper-${target}`:`thesis-${target}`;requestAnimationFrame(()=>document.getElementById(id)?.scrollIntoView({behavior:'instant',block:'start'}));}else window.scrollTo({top:0,behavior:'instant'});if(changed&&location.hash){main.focus({preventScroll:true});document.querySelector('#announcement').textContent=`${document.title} opened`;}}
  document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.getAttribute('href')==='#main'){e.preventDefault();main.focus({preventScroll:true});main.scrollIntoView({behavior:'instant',block:'start'});return;}if(b.hasAttribute('data-publications')){openPublications(b);return}if(b.dataset.publicationSection){dialog.querySelector('#publication-'+b.dataset.publicationSection)?.scrollIntoView({behavior:'instant',block:'start'});return}if(b.dataset.repo){openRepository(b.dataset.repo,b);return}if(b.hasAttribute('data-close-dialog')){closeDialog();return}if(b.hasAttribute('data-dialog-nav')){closeDialog();return}if(b.dataset.method){const id=b.dataset.method;document.querySelectorAll('[data-method]').forEach(t=>{t.setAttribute('aria-selected',String(t===b));t.tabIndex=t===b?0:-1});document.querySelector('#method-panel').innerHTML=methodPanel(id);document.querySelector('#method-panel').setAttribute('aria-labelledby',`method-tab-${id}`);return}if(b.dataset.stage){selectStage(b.dataset.stage);return}if(b.dataset.group){filters.group=b.dataset.group;refreshCards();return}if(b.hasAttribute('data-reset-filters')){filters={q:'',group:'all',type:'all'};document.querySelector('#repo-search').value='';document.querySelector('#type-filter').value='all';refreshCards();}});
  document.addEventListener('input',e=>{if(e.target.id==='repo-search'){filters.q=e.target.value;refreshCards()}});
  document.addEventListener('change',e=>{if(e.target.id==='type-filter'){filters.type=e.target.value;refreshCards()}});
  document.addEventListener('keydown',e=>{if(e.target.matches('[data-method]')&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('[data-method]')],i=tabs.indexOf(e.target);const target=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[target].focus();tabs[target].click();}});
  dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
  window.addEventListener('hashchange',render);
  render();
})();
